with eligible as (select s.* from departments s where not exists (select 1 from employees c where c.dept_id = s.id and c.manager_id is null)) select case when budget >= 3775000 then 'LARGE' else 'SMALL' end as budget_tier, dept_name, location, count(distinct location) as distinct_locations, count(*) filter (where location = 'Tokyo') as tokyo_rows, count(*) as event_count from eligible group by budget_tier, dept_name, location;
